1	// Single fulfilment path for a paid Stripe Checkout session, shared by BOTH the
2	// success-redirect route and the webhook. Plain server module (not "use server").
3	//
4	// WHY THIS EXISTS (2026-07-25)
5	// Fulfilment used to live in `app/api/stripe/confirm/route.ts` and was gated on
6	// whether `creditCheckoutSession()` returned true. That boolean is true only for
7	// the caller that won the race to insert the wallet credit — and the webhook
8	// calls the same function and discards the result. So:
9	//
10	//   * Race: the webhook's insert lands first, the confirm request gets P2002,
11	//     `credited === false`, and the redirect quietly lands on an empty page.
12	//     $249 charged, $249 credited, no server, no error, no notification.
13	//   * Deterministic: the customer closes the tab before `success_url` resolves,
14	//     so the confirm route never runs at all. Same outcome, 100% reproducible.
15	//
16	// Stripe's own guidance is explicit that a browser redirect must not be the
17	// fulfilment trigger. Now BOTH callers run this, and a `FulfilledSession` row —
18	// its own marker, not a side effect of crediting — decides the single winner.
19	
20	import { db } from "./db";
21	import { classifyCheckoutSession, creditCheckoutSession, retrieveCheckoutSession } from "./stripe";
22	import { placeOrder } from "./order";
23	import { applyResize } from "./resize";
24	import { applyDiskExpand } from "./disk-expand";
25	
26	export type FulfilResult = {
27	  /** Where the browser should end up. The webhook ignores this. */
28	  redirect: string;
29	  /** True when THIS call performed the fulfilment work. */
30	  fulfilled: boolean;
31	  kind: "order" | "resize" | "diskExpand" | "topup" | "none";
32	  error?: string;
33	};
34	
35	/**
36	 * Claim exclusive responsibility for fulfilling `sessionId`.
37	 * Returns false when another caller already holds the claim — the UNIQUE index,
38	 * not a read-then-write check, is what makes this safe under concurrency.
39	 */
40	async function claim(sessionId: string, kind: string): Promise<boolean> {
41	  try {
42	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
43	    return true;
44	  } catch (e) {
45	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
46	    throw e;
47	  }
48	}
49	
50	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
51	  await db.fulfilledSession
52	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
53	    .catch(() => {});
54	}
55	
56	/**
57	 * Tell the customer their money is safe and someone knows. Called only on a path
58	 * where the card HAS cleared and fulfilment did not happen, so silence is the one
59	 * outcome that is never acceptable.
60	 */
61	async function notifyStalled(userId: string) {
62	  await db.notification
63	    .create({
64	      data: {
65	        userId,
66	        title: "Payment received — we couldn't finish setting up your server",
67	        body: "Your payment is safe and sitting in your wallet. Our team has been alerted; deploy again or contact support and we'll sort it out.",
68	        href: "/dashboard/billing",
69	      },
70	    })
71	    .catch(() => {});
72	}
73	
74	/**
75	 * Credit the wallet and fulfil whatever the session was for, exactly once.
76	 * Safe to call repeatedly and concurrently from the redirect and the webhook.
77	 *
78	 * THROWS when Stripe cannot be read. That is deliberate and it is the fix for the
79	 * defect found on 2026-07-27: this function used to ask three helpers for the
80	 * session, each of which swallowed every error into `null`, so a transient Stripe
81	 * failure was indistinguishable from "no purchase metadata" and fell through to
82	 * the top-up branch below reporting `fulfilled: true`. A real order then had its
83	 * card charged with no server, no FulfilledSession row and no notification — and
84	 * because the webhook returns 200 either way, Stripe never retried it. A throw
85	 * lands the browser on `?pending=1` (see app/api/stripe/confirm) and puts the
86	 * failure in the webhook's log, which is loud; declaring it a top-up was silent.
87	 */
88	export async function fulfilCheckoutSession(sessionId: string, base = ""): Promise<FulfilResult> {
89	  // ONE retrieve, one view of the session, shared by the credit and the routing.
90	  const session = await retrieveCheckoutSession(sessionId);
91	  const purpose = classifyCheckoutSession(session);
92	
93	  // Nothing was paid (an abandoned session id, or one replayed before capture).
94	  // Never claim fulfilment for money that has not arrived.
95	  if (purpose.kind === "unpaid") {
96	    return { redirect: `${base}/dashboard/billing`, fulfilled: false, kind: "none" };
97	  }
98	
99	  // Crediting is separately idempotent (UNIQUE stripeSessionId on the wallet
100	  // transaction). We deliberately IGNORE its return value now — it reports who
101	  // won the credit race, which is not the same question as "has this been
102	  // fulfilled", and conflating the two was the bug. A THROW, however, is not a
103	  // race: the money has not reached the wallet, so nothing below may spend it.
104	  await creditCheckoutSession(session);
105	
106	  // Purchase metadata is present but cannot be trusted. Retrying will never fix
107	  // it, so claim the session and record the failure exactly like a failed order:
108	  // reconcilable, and the customer is told. What it must NEVER become is a silent
109	  // wallet top-up, which is precisely what the old `null` fall-through produced.
110	  if (purpose.kind === "unreadable") {
111	    if (await claim(sessionId, "unreadable")) {
112	      await settle(sessionId, "FAILED", purpose.detail);
113	      if (purpose.userId) await notifyStalled(purpose.userId);
114	    }
115	    return {
116	      redirect: `${base}/dashboard/billing?paid=1`,
117	      fulfilled: false,
118	      kind: "none",
119	      error: purpose.detail,
120	    };
121	  }
122	
123	  const order = purpose.kind === "order" ? purpose : null;
124	  if (order) {
125	    if (!(await claim(sessionId, "order"))) {
126	      return { redirect: `${base}/dashboard/servers`, fulfilled: false, kind: "order" };
127	    }
128	    try {
129	      const user = await db.user.findUnique({ where: { id: order.userId } });
130	      if (!user) throw new Error("user not found for paid order");
131	      // Settle the price stamped on the session BEFORE the card was charged — never
132	      // a fresh quote taken now. The customer has already paid the card leg of that
133	      // exact total; re-pricing here and taking the difference out of the wallet is
134	      // the H2 incident (see OrderPrice in lib/order.ts). This is the same shape as
135	      // the resize and disk-expand branches below, which have always passed the
136	      // amount through metadata for this reason.
137	      // No request-scoped IP on the fulfil path (this can run in the webhook), so the
138	      // per-IP cap can't be enforced here — the per-account unique still holds, and
139	      // the first-month-free HOLD was already reserved (per-account AND per-IP) before
140	      // the card was charged, so the double-claim race is closed regardless. Fulfilment
141	      // CONFIRMS that hold via `promoReservationToken` rather than contending for a
142	      // fresh claim. `campaign` rides in via metadata so attribution survives the card
143	      // round-trip even in the webhook (no cookies).
144	      const serverId = await placeOrder(user, order.intent, order.sold, {
145	        ipHash: null,
146	        campaign: order.campaign,
147	        promoReservationToken: order.promoReservationToken,
148	        // Same discipline as the promo hold: the coupon was RESERVED (per-person + global
149	        // cap) before the card was charged, and placeOrder CONFIRMS that hold via this
150	        // token rather than contending for a fresh claim — no double-claim, no over-charge.
151	        couponReservationToken: order.couponReservationToken,
152	      });
153	      await settle(sessionId, "DONE", serverId);
154	      return { redirect: `${base}/dashboard/servers/${serverId}`, fulfilled: true, kind: "order" };
155	    } catch (e) {
156	      // Payment is captured and the funds are in the wallet — record the failure
157	      // so it is reconcilable rather than invisible, and tell the customer.
158	      const msg = String((e as Error)?.message ?? e);
159	      await settle(sessionId, "FAILED", msg);
160	      await notifyStalled(order.userId);
161	      return { redirect: `${base}/dashboard/deploy?paid=1`, fulfilled: false, kind: "order", error: msg };
162	    }
163	  }
164	
165	  const resize = purpose.kind === "resize" ? purpose : null;
166	  if (resize) {
167	    const back = `${base}/dashboard/servers/${resize.serverId}`;
168	    if (!(await claim(sessionId, "resize"))) {
169	      return { redirect: back, fulfilled: false, kind: "resize" };
170	    }
171	    try {
172	      await applyResize({
173	        serverId: resize.serverId,
174	        planId: resize.planId,
175	        actorUserId: resize.userId,
176	        chargeCents: resize.chargeCents,
177	      });
178	      await settle(sessionId, "DONE", resize.serverId);
179	      return { redirect: back, fulfilled: true, kind: "resize" };
180	    } catch (e) {
181	      const msg = String((e as Error)?.message ?? e);
182	      await settle(sessionId, "FAILED", msg);
183	      await notifyStalled(resize.userId);
184	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "resize", error: msg };
185	    }
186	  }
187	
188	  const expand = purpose.kind === "diskExpand" ? purpose : null;
189	  if (expand) {
190	    const back = `${base}/dashboard/servers/${expand.serverId}`;
191	    if (!(await claim(sessionId, "diskExpand"))) {
192	      return { redirect: `${back}?tab=resize`, fulfilled: false, kind: "diskExpand" };
193	    }
194	    try {
195	      await applyDiskExpand({
196	        serverId: expand.serverId,
197	        addGB: expand.addGB,
198	        actorUserId: expand.userId,
199	        chargeCents: expand.chargeCents,
200	      });
201	      await settle(sessionId, "DONE", expand.serverId);
202	      return { redirect: `${back}?tab=resize`, fulfilled: true, kind: "diskExpand" };
203	    } catch (e) {
204	      const msg = String((e as Error)?.message ?? e);
205	      await settle(sessionId, "FAILED", msg);
206	      await notifyStalled(expand.userId);
207	      return { redirect: `${back}?paid=1`, fulfilled: false, kind: "diskExpand", error: msg };
208	    }
209	  }
210	
211	  // Plain wallet top-up: crediting above is the whole job. Reached ONLY when the
212	  // session genuinely carried no purchase metadata — never because we failed to
213	  // read it (that throws) and never because we failed to parse it ("unreadable").
214	  return { redirect: `${base}/dashboard/billing?paid=1`, fulfilled: true, kind: "topup" };
215	}
216

1	import Stripe from "stripe";
2	import type { Prisma } from "@prisma/client";
3	import { db } from "./db";
4	import type { OrderIntent, OrderPrice } from "./order";
5	import { orderPriceOf, orderQuote, parseOrderPrice } from "./order";
6	import { sanitizeCampaign } from "./promo-redemption";
7	import { invoiceCreateData } from "./invoices";
8	
9	export function stripeConfigured(): boolean {
10	  return !!process.env.STRIPE_SECRET_KEY;
11	}
12	
13	let client: Stripe | null = null;
14	
15	export function stripe(): Stripe {
16	  if (!process.env.STRIPE_SECRET_KEY) throw new Error("Stripe is not configured");
17	  if (!client) client = new Stripe(process.env.STRIPE_SECRET_KEY);
18	  return client;
19	}
20	
21	/** Stripe's hard limit on a single metadata VALUE. */
22	export const STRIPE_METADATA_VALUE_MAX = 500;
23	
24	/**
25	 * How long an order Checkout session stays payable. Kept SHORT (1h) on purpose: the
26	 * managed first-month-free hold (lib/promo-redemption.ts reserveFirstMonthFree) lives
27	 * exactly as long as the session can still be paid, so a shorter session means a
28	 * customer who abandons checkout gets their one-time offer back sooner. Stripe's
29	 * accepted range is 30 min – 24 h; 1 h sits comfortably inside it.
30	 */
31	export const ORDER_CHECKOUT_EXPIRES_MS = 60 * 60 * 1000;
32	
33	/**
34	 * Serialise a payload for Stripe metadata, refusing rather than truncating.
35	 *
36	 * WHY THIS EXISTS. Every one of these payloads used to be written as
37	 * `JSON.stringify(x).slice(0, 490)`. A slice through JSON produces a string that
38	 * is no longer JSON, and the consumer's `JSON.parse` throws inside a `try` that
39	 * returns `null` on failure — at which point `fulfilCheckoutSession` cannot see an
40	 * order, a resize or a disk expansion in the session, and falls through to its
41	 * plain wallet-top-up branch. The customer's card is charged, the money lands in
42	 * their wallet, **no server is created, no error is shown and no failure row is
43	 * written**. Silent, and invisible from every surface we own.
44	 *
45	 * The correct behaviour was already argued for elsewhere in this file, about the
46	 * card leg: "Refuse to open a session rather than take the money and discover it
47	 * at confirm time — nothing has been charged at this point." That reasoning
48	 * applies identically here, so it is applied identically. Throwing happens BEFORE
49	 * `checkout.sessions.create`, so the customer sees a failure on a page where they
50	 * have paid nothing, which is the cheapest possible moment to fail.
51	 *
52	 * Never re-introduce a slice here. If a payload legitimately outgrows the cap, the
53	 * fix is to persist it and put a key in metadata — never to send half of it.
54	 */
55	export function packMetadata(label: string, payload: unknown): string {
56	  const json = JSON.stringify(payload);
57	  if (json.length > STRIPE_METADATA_VALUE_MAX) {
58	    throw new Error(
59	      `${label} is ${json.length} characters, over Stripe's ${STRIPE_METADATA_VALUE_MAX}-character metadata limit. ` +
60	        `Refusing to create a payment session rather than send a truncated payload that would take the money and ` +
61	        `provision nothing.`,
62	    );
63	  }
64	  return json;
65	}
66	
67	/**
68	 * Create a Checkout session that pays for a VPS order directly (no wallet pre-fund).
69	 *
70	 * `amountCents` is the CARD leg only (the remainder after wallet credit); the FULL
71	 * order total rides along in metadata as `nxeonOrderPrice` so the confirm route can
72	 * settle the price this order was SOLD at instead of re-pricing it once the card
73	 * has already cleared. That re-pricing — and the silent wallet draw that paid for
74	 * it — is the H2 incident described on `OrderPrice` in lib/order.ts.
75	 *
76	 * `sold` lets the caller hand in the very quote it split the payment from, so the
77	 * card leg and the stamped total are two halves of ONE pricing. When it is omitted
78	 * the order is priced here, once, at the moment the session is created — still
79	 * before any money moves, which is the property that matters.
80	 */
81	export async function createOrderCheckout(
82	  user: { id: string; email: string },
83	  amountCents: number,
84	  intent: OrderIntent,
85	  sold?: OrderPrice | null,
86	  campaign?: string,
87	  /**
88	   * The managed first-month-free HOLD token, when this order was sold WITH the free
89	   * month. Reserved by `reserveFirstMonthFree` BEFORE this session is created, so the
90	   * discounted price stamped here is already backed by an exclusive hold. It rides in
91	   * metadata so fulfilment can CONFIRM the hold (never a fresh, contended claim) and
92	   * the `checkout.session.expired` webhook can RELEASE it. Null/omitted for a
93	   * full-price order (nothing to confirm).
94	   */
95	  promoReservationToken?: string | null,
96	  /**
97	   * The checkout-coupon HOLD token, when this order was sold WITH a coupon discount.
98	   * Reserved by `reserveOrderCoupon` (lib/coupon-redemption.ts) BEFORE this session is
99	   * created, so the discounted price stamped here is already backed by an exclusive hold
100	   * (per-person + a global-cap slot). It rides in metadata so fulfilment can CONFIRM the
101	   * hold (never a fresh, contended claim) and the `checkout.session.expired` webhook can
102	   * RELEASE it. Null/omitted for a full-price order.
103	   */
104	  couponReservationToken?: string | null,
105	): Promise<string | null> {
106	  if (!stripeConfigured() || amountCents <= 0) return null;
107	  const base = process.env.APP_URL ?? "http://localhost:3000";
108	  const price = sold ?? orderPriceOf(await orderQuote(intent));
109	  // The card leg is a PART of the TAX-INCLUSIVE total (net + VAT); a card charge
110	  // larger than the whole order means the two were priced against different worlds and
111	  // the wallet would have to absorb a negative. Refuse to open a session rather than
112	  // take the money and discover it at confirm time — nothing has been charged here.
113	  const orderTotalCents = price.chargeCents + (price.taxCents ?? 0);
114	  if (orderTotalCents < amountCents) {
115	    throw new Error(
116	      `Order checkout: card leg ${amountCents}c exceeds the order total ${orderTotalCents}c`,
117	    );
118	  }
119	  // SSH keys are long; keep them out of Stripe metadata (500-char cap) — addable after deploy.
120	  const slim: OrderIntent = { ...intent, sshPublicKey: undefined, sshKeyName: undefined };
121	  const session = await stripe().checkout.sessions.create({
122	    mode: "payment",
123	    customer_email: user.email,
124	    // Bound the session's payable life so an abandoned checkout returns the customer's
125	    // first-month-free hold quickly (the hold's reservedUntil is pinned just past this).
126	    expires_at: Math.floor((Date.now() + ORDER_CHECKOUT_EXPIRES_MS) / 1000),
127	    line_items: [
128	      {
129	        price_data: {
130	          currency: "usd",
131	          product_data: { name: `Nxeon VPS — ${intent.hostname}` },
132	          unit_amount: amountCents,
133	        },
134	        quantity: 1,
135	      },
136	    ],
137	    metadata: {
138	      nxeonUserId: user.id,
139	      nxeonOrder: packMetadata("Order intent", slim),
140	      // Its OWN key, not a field inside `nxeonOrder`, so the two are independently
141	      // sized and a long intent can never displace the price.
142	      nxeonOrderPrice: packMetadata("Order price", price),
143	      // First-month-free ad campaign tag (from the /go link cookie), carried through
144	      // the card round-trip so the redemption records attribution at fulfil time —
145	      // the webhook has no request cookies to read it from.
146	      nxeonPromoCampaign: sanitizeCampaign(campaign),
147	      // The first-month-free HOLD token. Present only when the discounted price above
148	      // is backed by a reserved hold; fulfilment confirms it, expiry releases it.
149	      ...(promoReservationToken ? { nxeonPromoReservation: promoReservationToken } : {}),
150	      // The checkout-coupon HOLD token — same lifecycle as the promo one above, for the
151	      // coupon's per-person + global-cap slot. Present only on a coupon-discounted order.
152	      ...(couponReservationToken ? { nxeonCouponReservation: couponReservationToken } : {}),
153	    },
154	    success_url: `${base}/api/stripe/confirm?session_id={CHECKOUT_SESSION_ID}`,
155	    cancel_url: `${base}/dashboard/deploy?canceled=1`,
156	  });
157	  return session.url;
158	}
