252	/**
253	 * A cents amount that arrived from OUTSIDE this process (Stripe metadata) and is
254	 * about to be handed to `debitWallet`. Integer, non-negative, finite — anything
255	 * else is refused rather than coerced, for the same reason `parseOrderPrice`
256	 * refuses a half-valid price: the caller's `?? quote.prorateCents` fallback would
257	 * silently RE-PRICE the purchase at confirm time, which is the H2 incident.
258	 */
259	function parseChargeCents(raw: unknown): number | null {
260	  if (typeof raw !== "number" || !Number.isInteger(raw) || raw < 0) return null;
261	  return raw;
262	}
263	
264	function parseId(raw: unknown): string | null {
265	  return typeof raw === "string" && raw.length > 0 ? raw : null;
266	}
