376	/**
377	 * Retrieve a Checkout session ONCE. Throws when Stripe cannot be read — the caller
378	 * must never be able to mistake a transport failure for "this session is a top-up".
379	 */
380	export async function retrieveCheckoutSession(sessionId: string): Promise<Stripe.Checkout.Session> {
381	  if (!stripeConfigured()) throw new Error("Stripe is not configured");
382	  return stripe().checkout.sessions.retrieve(sessionId);
383	}
