385	/** Retrieve + classify in one step. Throws on a Stripe read failure, never lies. */
386	export async function getCheckoutPurpose(sessionId: string): Promise<CheckoutPurpose> {
387	  return classifyCheckoutSession(await retrieveCheckoutSession(sessionId));
388	}
