390	/**
391	 * True when this session's card payment is the FUNDING LEG of a purchase — a VPS
392	 * order, an upgrade, a disk expansion — rather than a wallet top-up the customer
393	 * bought for its own sake.
394	 *
395	 * The wallet is the settlement bus for every card-paid purchase: the card amount
396	 * is credited in, then the purchase debits the full total back out. That credit is
397	 * plumbing, not a product, and it must not be documented as one.
398	 *
399	 * REAL INCIDENT (2026-07-26 rehearsal, H3): every paid session got a PAID "Wallet
400	 * top-up" invoice here AND a PAID invoice from whatever it funded, so one $82.53
401	 * annual purchase produced `Wallet top-up $82.53` + `Starter VPS — Annual $82.53`
402	 * and the invoices page reported $165.06 paid lifetime — a customer reconciling
403	 * against their card statement saw twice their spend. Each document was internally
404	 * consistent; there were simply two of them for one payment. worker/billing.ts
405	 * already states the rule for the renewal path: "No invoice for the card leg …
406	 * a second document for the card portion would double-count the same revenue."
407	 *
408	 * Reads the same three metadata keys `lib/fulfil-checkout.ts` dispatches on, so
409	 * "did this session fund a purchase" has one answer, not two.
410	 */
411	export function isPurchaseLegSession(metadata: Stripe.Metadata | null | undefined): boolean {
412	  return !!(metadata?.nxeonOrder || metadata?.nxeonResize || metadata?.nxeonDiskExpand);
413	}
414	
415	/**
416	 * Credit a user's wallet for a completed Checkout session, idempotently.
417	 * Called from both the success-redirect confirm route (works without HTTPS)
418	 * and the webhook (belt-and-suspenders once HTTPS is available).
419	 * Returns true if a credit was applied this call.
420	 *
421	 * Takes the ALREADY-RETRIEVED session rather than an id: `fulfilCheckoutSession`
422	 * fetches it once and both the credit and the fulfilment routing read that single
423	 * object, so the two can never disagree about what this payment was (and a Stripe
424	 * read failure surfaces in one place, loudly, instead of four times as `null`).
425	 */
426	export async function creditCheckoutSession(session: Stripe.Checkout.Session): Promise<boolean> {
427	  const userId = session.metadata?.nxeonUserId;
428	  const cents = session.amount_total ?? 0;
429	  if (!userId || cents <= 0 || session.payment_status !== "paid") return false;
430	
431	  // Legacy guard: rows credited before `stripeSessionId` existed only recorded the
432	  // session id inside the description.
433	  const legacy = await db.walletTransaction.findFirst({
434	    where: { stripeSessionId: null, description: { contains: session.id } },
435	  });
436	  if (legacy) return false;
437	
438	  // Is this credit a product the customer bought, or the funding leg of something
439	  // else they bought? Only the first is a "Wallet top-up" and only the first gets
440	  // a billing document — see isPurchaseLegSession for the incident.
441	  const purchaseLeg = isPurchaseLegSession(session.metadata);
442	
443	  // Idempotency is enforced by the UNIQUE index on `stripeSessionId` — NOT by a
444	  // read-then-write check. The confirm-redirect and the webhook can arrive
445	  // concurrently (and /api/stripe/confirm is unauthenticated and replayable), so
446	  // only the database can safely decide the winner. P2002 == already credited.
447	  const ops: Prisma.PrismaPromise<unknown>[] = [
448	    db.walletTransaction.create({
449	      data: {
450	        userId,
451	        amountCents: cents,
452	        description: `Stripe payment (${session.id})`,
453	        stripeSessionId: session.id,
454	      },
455	    }),
456	    db.user.update({ where: { id: userId }, data: { balanceCents: { increment: cents } } }),
457	    db.notification.create({
458	      data: {
459	        userId,
460	        title: `Payment of $${(cents / 100).toFixed(2)} received`,
461	        href: "/dashboard/billing",
462	      },
463	    }),
464	  ];
465	  // Index of the invoice-create inside `ops`, or -1 when no invoice is issued
466	  // (a purchase leg). Used to recover the new invoice's id for the receipt email.
467	  let invoiceOpIndex = -1;
468	  if (!purchaseLeg) {
469	    // PAID invoice for the top-up. Created in the SAME guarded transaction as
470	    // the wallet credit, so the UNIQUE(stripeSessionId) constraint that makes
471	    // the credit idempotent also prevents a duplicate invoice on replay.
472	    //
473	    // A purchase leg is deliberately left undocumented HERE: the order, resize or
474	    // disk-expansion it funds issues the one invoice for the whole purchase, and
475	    // that document — not this one — is what the customer's card statement shows.
476	    // If the fulfilment then fails the money stays in the wallet as an ordinary
477	    // credit (ledger row + notification), and the invoice is issued by whatever it
478	    // is eventually spent on; inventing a top-up document at that point would
479	    // double-count the same dollars all over again the moment they deploy.
480	    // Remember WHERE in the batch this lands, so the created row's id can be read
481	    // back out of the transaction result. The receipt email promises the customer
482	    // an attached invoice, and it can only keep that promise if it knows the id.
483	    invoiceOpIndex = ops.length;
484	    ops.push(
485	      db.invoice.create({
486	        data: invoiceCreateData({
487	          userId,
488	          description: "Wallet top-up",
489	          status: "PAID",
490	          lineItems: [
491	            { description: "Wallet top-up", qty: 1, unitCents: cents, amountCents: cents },
492	          ],
493	        }),
494	      }),
495	    );
496	  }
497	  let invoiceId: string | undefined;
498	  try {
499	    const results = await db.$transaction(ops);
500	    if (invoiceOpIndex >= 0) {
501	      const created = results[invoiceOpIndex] as { id?: string } | undefined;
502	      invoiceId = created?.id;
503	    }
504	  } catch (e) {
505	    if ((e as { code?: string })?.code === "P2002") return false; // raced — already credited
506	    throw e;
507	  }
508	  // A funded wallet is the referred user's first paid action — reward both sides.
509	  try {
510	    const { maybeRewardReferral } = await import("./actions-growth");
511	    await maybeRewardReferral(userId);
512	  } catch { /* best-effort */ }
513	  try {
514	    const u = await db.user.findUnique({ where: { id: userId } });
515	    if (u) {
516	      const { sendMail, emails } = await import("./mailer");
517	      // Say what the money was for. On a purchase leg it is emphatically NOT a
518	      // top-up, and a receipt that calls it one is the same false statement the
519	      // duplicate invoice used to make, just in the customer's inbox.
520	      // The third argument is the promise, and it is the truth: we claim an attached
521	      // invoice only when there is an invoice id to attach. A purchase leg issues no
522	      // top-up invoice (the order does), so its receipt points at billing history
523	      // instead of promising a file that was never generated.
524	      const tpl = emails.receipt(
525	        `$${(cents / 100).toFixed(2)}`,
526	        purchaseLeg ? "your Nxeon order" : "wallet top-up",
527	        !!invoiceId,
528	      );
529	      // `kind` + `userId` hands this to the preference policy in lib/prefs.ts.
530	      // A receipt is ACCOUNT tier — suppressible by email if the customer turned
531	      // account email off. This is the one send site where that toggle actually
532	      // bites today, so it is the one that made the switch a lie.
533	      await sendMail({ to: u.email, subject: tpl.subject, html: tpl.html, userId, kind: "receipt", invoiceId });
534	    }
535	  } catch { /* best-effort */ }
536	  return true;
537	}
