79	   * is provisioned at plan.diskGB + extraDiskGB (worker/index.ts provision), so no
80	   * post-deploy expansion job is needed. Permanent — never shrinks.
81	   */
82	  extraDiskGB?: number;
83	  /** Checkout promo code (e.g. a "one free month" coupon), uppercased. */
84	  couponCode?: string;
85	  /**
86	   * Paid backup RETENTION tier bought at deploy time. FREE (included) or PLUS
87	   * (keep 7, priced monthly like the other add-ons). Round-tripped through Stripe
88	   * metadata, so it stays a tiny string.
89	   */
90	  backupTier?: BackupTier;
91	};
