93	/**
94	 * The price an order was SOLD at: the total, and the promo rate that produced it.
95	 * Fixed ONCE — before any money moves — and carried to the moment it is charged.
96	 *
97	 * REAL INCIDENT (2026-07-26 customer-journey rehearsal, H2). The card-paid deploy
98	 * path quoted a total, charged the CARD its share of that total at Stripe, and
99	 * then — on the confirm redirect, minutes or hours later — re-ran `orderQuote`
100	 * and debited whatever came back. That re-run includes `currentPromo(new Date())`,
101	 * and lib/promotions.ts always has an active sale that rotates by calendar date,
102	 * so a rotation between "customer clicked Deploy" and "customer came back from
103	 * Stripe" re-priced the order AFTER the card had cleared and took the difference
104	 * out of the wallet with no new consent. With no balance to take it from, the
105	 * payment was captured and no server was created.
106	 *
107	 * `lib/resize.ts` and `lib/disk-expand.ts` already carried the amount through
108	 * Stripe metadata for exactly this reason; the order path was the one that
109	 * re-derived it. Same rule as lib/renewal-quote.ts and lib/proration.ts: a figure
110	 * the customer was shown is not recomputed later, it is carried.
111	 *
112	 * `promoPercent` and `promoName` travel WITH the total because they are not
113	 * decoration. `Server.termPromoPercent` records the rate a term was actually sold
114	 * at (every later proration prices against it), and the promo name is the ledger
115	 * and invoice text the customer reads. Honouring a 30%-off price while stamping
116	 * today's 15% would hand every later proration the wrong basis and print a
117	 * discount on the invoice that does not match the money taken.
118	 */
119	export type OrderPrice = {
120	  /**
121	   * The NET (pre-tax) total the customer consented to, in cents. Its meaning is
122	   * unchanged by Finding 1 — every promo/coupon/proration figure is computed against
123	   * this net. The amount actually CHARGED is `chargeCents + (taxCents ?? 0)`.
124	   */
125	  chargeCents: number;
126	  /** Promo rate (%) that produced it; persisted as `Server.termPromoPercent`. */
127	  promoPercent: number;
128	  /** Promo name for the ledger / invoice line, e.g. "Summer Sale". */
129	  promoName: string;
130	  /**
131	   * VAT/GST on the net (Finding 1), carried through the card round-trip so the
132	   * confirm route settles the SAME tax-inclusive total the card leg was split from
133	   * — never re-derived after the card cleared. Absent on legacy/full-price sessions,
134	   * in which case the charge path recomputes it from the owner's country (0 by
135	   * default), which can only ever undertax, the conservative direction.
136	   */
137	  taxCents?: number;
138	  taxRatePercent?: number;
139	  taxCountry?: string;
140	};
141	
142	/**
143	 * The sold price implied by a quote — the ONE place a quote becomes a price. An
144	 * optional resolved tax context stamps the VAT the card round-trip must settle.
145	 */
146	export function orderPriceOf(
147	  quote: {
148	    chargeCents: number;
149	    promo: { discountPercent: number; name: string };
150	  },
151	  tax?: { taxCents: number; ratePercent: number; country: string } | null,
152	): OrderPrice {
153	  return {
154	    chargeCents: quote.chargeCents,
155	    promoPercent: quote.promo.discountPercent,
156	    promoName: quote.promo.name,
157	    ...(tax
158	      ? { taxCents: tax.taxCents, taxRatePercent: tax.ratePercent, taxCountry: tax.country }
159	      : {}),
160	  };
161	}
162	
163	/**
164	 * Parse a sold price back off Stripe metadata. Returns null unless EVERY field is
165	 * well-formed: a half-parsed price would be worse than no price at all, because
166	 * the caller's fallback (re-quote) is at least internally consistent.
167	 */
168	export function parseOrderPrice(raw: unknown): OrderPrice | null {
169	  let obj: unknown = raw;
170	  if (typeof raw === "string") {
171	    try {
172	      obj = JSON.parse(raw);
173	    } catch {
174	      return null;
175	    }
176	  }
177	  if (!obj || typeof obj !== "object") return null;
178	  const { chargeCents, promoPercent, promoName, taxCents, taxRatePercent, taxCountry } =
179	    obj as Record<string, unknown>;
180	  if (typeof chargeCents !== "number" || !Number.isInteger(chargeCents) || chargeCents < 0) return null;
181	  if (typeof promoPercent !== "number" || !Number.isInteger(promoPercent)) return null;
182	  if (promoPercent < 0 || promoPercent > 100) return null;
183	  // Tax fields are ADDITIVE and lenient: a session written before Finding 1 (or with a
184	  // malformed tax field) carries none, and the charge path recomputes tax from the
185	  // owner's country — which undertaxes at worst, never overcharges.
186	  const tc = typeof taxCents === "number" && Number.isInteger(taxCents) && taxCents >= 0 ? taxCents : 0;
187	  const tr =
188	    typeof taxRatePercent === "number" && Number.isFinite(taxRatePercent) && taxRatePercent >= 0
189	      ? taxRatePercent
190	      : 0;
191	  return {
192	    chargeCents,
193	    promoPercent,
194	    promoName: typeof promoName === "string" ? promoName : "",
195	    taxCents: tc,
196	    taxRatePercent: tr,
197	    taxCountry: typeof taxCountry === "string" ? taxCountry : "",
198	  };
199	}
