262	/** Validate + price an order without placing it. Throws OrderError on any problem. */
263	export async function orderQuote(intent: OrderIntent, opts?: { suppressPromo?: boolean }) {
264	  const parsed = orderSchema.safeParse(intent);
265	  if (!parsed.success) throw new OrderError(parsed.error.issues[0]?.message ?? "Invalid input.");
266	  const plan = await db.plan.findUnique({ where: { id: intent.planId } });
267	  const os = await db.osTemplate.findUnique({ where: { id: intent.osTemplateId } });
268	  if (!plan?.active || !os?.active) throw new OrderError("Plan or OS not available.");
269	  if (plan.ramMB < os.minRamMB || plan.diskGB < os.minDiskGB) {
270	    throw new OrderError(
271	      `${os.name} needs at least ${os.minRamMB / 1024} GB RAM and ${os.minDiskGB} GB disk — choose a larger plan.`,
272	    );
273	  }
274	  const term = vpsTerm(Number(intent.termMonths ?? 1));
275	  // The admin-configured ANNUAL discount, resolved ONCE here and passed to
276	  // `vpsTermPriceCents` so the annual term is charged at the same rate the deploy
277	  // wizard displayed and every renewal will bill. Ignored for non-annual terms.
278	  const annualPct = await annualDiscountPct();
279	  const ipCents = intent.dedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0;
280	
281	  // Extra root disk, priced per GB/month and multiplied over the term exactly
282	  // like the dedicated-IP add-on (and, like it, NOT discounted by the term or the
283	  // promo — the customer pays the same $/GB whichever term they pick, and renews
284	  // at the same rate). Growth is one-way: this is permanent for the server.
285	  const extraDiskGB = normalizeExtraDiskGB(intent.extraDiskGB);
286	  const extraDiskPerGb = extraDiskGB > 0 ? await extraDiskPerGbCents() : 0;
287	  const extraDiskMonthlyCents = extraDiskCentsAt(extraDiskGB, extraDiskPerGb);
288	  const extraDiskCents = extraDiskMonthlyCents * term.months;
289	  if (effectiveDiskGB(plan.diskGB, extraDiskGB) > EXTRA_DISK_MAX_TOTAL_GB) {
290	    throw new OrderError(`A server's disk tops out at ${EXTRA_DISK_MAX_TOTAL_GB} GB.`);
291	  }
292	
293	  // Paid backup RETENTION tier, priced per month and multiplied over the term
294	  // exactly like the extra-disk add-on (NOT promo-discounted — the customer pays
295	  // the same $/mo whichever term or promo, and renews at the same rate through
296	  // renewalCharge). Only PLUS is paid; FREE (the included tier) is $0.
297	  const backupTier = normalizeBackupTier(intent.backupTier);
298	  const backupMonthlyCents =
299	    backupTier === "FREE" ? 0 : backupTierMonthlyCents(backupTier, await backupPlusMonthlyCents());
300	  const backupCents = backupMonthlyCents * term.months;
301	
302	  // Seasonal promo = HONEST intro discount on the plan's FIRST-term charge only.
303	  // The regular term price (vpsTermPriceCents) is what renewals bill unchanged in
304	  // worker/billing.ts — so the strikethrough shown on the marketing pages is the
305	  // real renewal price and this discounted value is the real first-term price.
306	  // Marketing displays promoPriceCents(regular) too, so displayed === charged.
307	  // (Dedicated IP is billed at full price; the promo only touches the plan.)
308	  const regularPlanCents = vpsTermPriceCents(plan.priceCents, term.months, annualPct);
309	  const promo = currentPromo(new Date());
310	  // The promo is now MANAGED: the owner can switch it off, and every claim is
311	  // capped 1/account + 1/IP (lib/promo-redemption.ts). When the toggle is off the
312	  // quote shows — and placeOrder charges — the full price, so display === charged
313	  // on the disabled path. When it is on, the quote shows the first-month-free
314	  // price and the atomic claim in placeOrder's tx is the final arbiter of whether
315	  // the credit is actually granted (a lost race there is charged full).
316	  // `suppressPromo` prices this quote at FULL price even when the promo is on —
317	  // the card path uses it to re-quote for a customer who has already redeemed
318	  // (per-account/IP), so their Stripe leg and stamped total are full, not free.
319	  // The first-month-free promo is scoped to Shared Web Hosting only — VPS always
320	  // bills full. `firstMonthFreeAppliesTo("VPS")` is false, so promoEnabled is
321	  // false here and planFirstTermCents falls through to the regular term total.
322	  const promoEnabled =
323	    firstMonthFreeAppliesTo("VPS") && !opts?.suppressPromo && (await firstMonthFreeEnabled());
324	  // First-month-free must credit exactly ONE MONTH — not zero a multi-month term.
325	  // A naive promoPriceCents(termTotal) at 100% off would give a 36-month term 3
326	  // YEARS free. So we subtract one month of the plan's rate from the term total.
327	  // For a 1-month term this lands at $0 (genuinely first month free); for a 12/24/
328	  // 36-month term the customer pays the term minus one month. Renewals bill the
329	  // full vpsTermPriceCents unchanged (worker/billing.ts) — displayed === charged.
330	  const planFirstTermCents =
331	    promoEnabled && promo.firstMonthFree
332	      ? Math.max(0, regularPlanCents - plan.priceCents)
333	      : regularPlanCents;
334	  // The one-month credit this order gets IF the atomic claim succeeds. 0 when the
335	  // promo is off. placeOrder adds it back to charge full when the claim is lost.
336	  const promoCreditCents = regularPlanCents - planFirstTermCents;
337	
338	  // Optional checkout coupon: a service-locked, term-capped discount on the PLAN
339	  // portion only (not the dedicated-IP or extra-disk add-ons). Never throws for a
340	  // bad code — an invalid coupon leaves the price at full and surfaces `couponError`
341	  // so the deploy preview can show it; the redemption itself (count + per-user +
342	  // per-IP guards) is claimed atomically in placeOrder.
343	  let couponId: string | null = null;
344	  let couponDiscountCents = 0;
345	  let couponLabel = "";
346	  let couponError = "";
347	  let couponMaxRedemptions: number | null = null;
348	  let couponFirstTimeOnly = false;
349	  const code = (intent.couponCode ?? "").trim().toUpperCase();
350	  if (code) {
351	    if (!(await getSettingBool("coupons_enabled", true))) {
352	      couponError = "Promo codes are currently disabled.";
353	    } else {
354	      const coupon = await db.coupon.findUnique({ where: { code } });
355	      if (!coupon) {
356	        couponError = "That code isn’t valid.";
357	      } else {
358	        const verdict = couponOrderDiscountCents(
359	          {
360	            kind: coupon.kind,
361	            value: coupon.value,
362	            serviceKind: coupon.serviceKind,
363	            planSlug: coupon.planSlug,
364	            maxTermMonths: coupon.maxTermMonths,
365	            active: coupon.active,
366	            expiresAt: coupon.expiresAt,
367	            maxRedemptions: coupon.maxRedemptions,
368	            timesRedeemed: coupon.timesRedeemed,
369	            minAmountCents: coupon.minAmountCents,
370	          },
371	          {
372	            serviceKind: "VPS",
373	            planSlug: plan.slug,
374	            planMonthlyCents: plan.priceCents,
375	            termMonths: term.months,
376	            planChargeCents: planFirstTermCents,
377	          },
378	          new Date(),
379	        );
380	        if (verdict.ok) {
381	          couponId = coupon.id;
382	          couponDiscountCents = verdict.discountCents;
383	          couponLabel = verdict.label;
384	          couponMaxRedemptions = coupon.maxRedemptions;
385	          couponFirstTimeOnly = coupon.firstTimeOnly;
386	        } else {
387	          couponError = verdict.error;
388	        }
389	      }
390	    }
391	  }
392	
393	  const chargeCents = planFirstTermCents - couponDiscountCents + ipCents + extraDiskCents + backupCents;
394	  return {
395	    plan,
396	    os,
397	    term,
398	    chargeCents,
399	    // The annual-discount rate this quote was priced at — snapshot onto the Server at
400	    // sale (Finding 2) so every later proration reads the SAME basis and a round trip
401	    // nets to zero even if the admin retunes `annual_discount_percent` in between.
402	    annualPct,
403	    promo,
404	    promoCreditCents,
405	    regularPlanCents,
406	    extraDiskGB,
407	    extraDiskMonthlyCents,
408	    extraDiskCents,
409	    backupTier,
410	    backupMonthlyCents,
411	    backupCents,
412	    couponId,
413	    couponDiscountCents,
414	    couponLabel,
415	    couponError,
416	    couponMaxRedemptions,
417	    couponFirstTimeOnly,
418	  };
419	}
