1	/**
2	 * Managed first-month-free promotion — the atomic redemption core.
3	 *
4	 * This mirrors lib/order.ts `claimOrderCoupon`: a conditional INSERT guarded by
5	 * two @@unique constraints (PromoRedemption `@@unique([promoId,userId])` and
6	 * `@@unique([promoId,ipHash])`) that runs INSIDE the order's charge transaction.
7	 * If the insert violates either constraint (this account OR this IP already
8	 * redeemed) it returns `{ claimed: false }` — it never throws for that case — so
9	 * the caller can charge the FULL price and still complete the order.
10	 *
11	 * THE MONEY RULE (owner will review this file personally):
12	 *   - The free-month credit is applied to an order ONLY when `claimed === true`.
13	 *   - If the claim is lost (already redeemed by account/IP) OR the promo is
14	 *     switched off via the `first_month_free_enabled` setting, the customer is
15	 *     charged the FULL price. The order still succeeds — it just isn't free.
16	 *   - The caps are FIXED at 1/account + 1/IP and are enforced ONLY by the two
17	 *     unique constraints. There is no configurable cap to drift out of sync.
18	 *
19	 * WHY A TYPED VIEW instead of `db.promoRedemption` directly: the Prisma client in
20	 * this tree is symlinked from prod and is only regenerated at deploy time, so its
21	 * types do not yet know about the new PromoRedemption model. Rather than sprinkle
22	 * `as any` across four money-critical order flows, every raw-delegate access is
23	 * contained HERE behind `promoDelegate(...)`, and the rest of the codebase calls
24	 * the strongly-typed helpers below. When the client is regenerated the runtime is
25	 * identical; only these casts become redundant.
26	 */
27	
28	import { randomUUID } from "crypto";
29	import { Prisma } from "@prisma/client";
30	import { db } from "./db";
31	
32	/** The single managed promo id. */
33	export const FIRST_MONTH_FREE_PROMO_ID = "first-month-free";
34	
35	/**
36	 * Redemption row lifecycle. A wallet-atomic flow inserts a CONSUMED grant in one
37	 * step; the card/Stripe flow first inserts a RESERVED hold (before the card is
38	 * charged) and later confirms it to CONSUMED. Both states physically occupy the two
39	 * unique slots, so a live hold blocks a second claim exactly like a grant.
40	 */
41	export const PROMO_STATE = { RESERVED: "RESERVED", CONSUMED: "CONSUMED" } as const;
42	export type PromoState = (typeof PROMO_STATE)[keyof typeof PROMO_STATE];
43	
44	/** Products the promo can be granted on (matches PromoRedemption.serviceType). */
45	export type PromoServiceType = "VPS" | "HOSTING" | "EMAIL" | "GAME";
46	
47	/** A minimal, honestly-typed shape of the row we read back. */
48	export type PromoRedemptionRow = {
49	  id: string;
50	  promoId: string;
51	  userId: string;
52	  ipHash: string | null;
53	  serviceType: string;
54	  campaign: string;
55	  orderRef: string | null;
56	  renewed: boolean;
57	  renewedAt: Date | null;
58	  chargedCents: number;
59	  state: string;
60	  reservedUntil: Date | null;
61	  reservationToken: string | null;
62	  createdAt: Date;
63	};
64	
65	/**
66	 * The subset of the PromoRedemption Prisma delegate this module uses, typed by
67	 * hand so the call sites stay type-checked even before the client is regenerated.
68	 */
69	type PromoWhere = {
70	  promoId?: string;
71	  userId?: string;
72	  ipHash?: string;
73	  orderRef?: string;
74	  renewed?: boolean;
75	  state?: string;
76	  reservationToken?: string;
77	  reservedUntil?: { lt: Date };
78	};
79	type PromoDelegate = {
80	  create(args: {
81	    data: {
82	      promoId?: string;
83	      userId: string;
84	      ipHash: string | null;
85	      serviceType: string;
86	      campaign: string;
87	      orderRef?: string | null;
88	      chargedCents: number;
89	      state?: string;
90	      reservedUntil?: Date | null;
91	      reservationToken?: string | null;
92	    };
93	    select?: { id: true };
94	  }): Promise<{ id: string }>;
95	  findUnique(args: {
96	    where: { promoId_userId: { promoId: string; userId: string } };
97	    select?: { id: true };
98	  }): Promise<{ id: string } | null>;
99	  findFirst(args: {
100	    where: PromoWhere;
101	    select?: { id: true };
102	  }): Promise<{ id: string } | null>;
103	  findMany(args?: {
104	    where?: PromoWhere;
105	    orderBy?: { createdAt: "asc" | "desc" };
106	  }): Promise<PromoRedemptionRow[]>;
107	  updateMany(args: {
108	    where: PromoWhere;
109	    data: { renewed?: boolean; renewedAt?: Date; state?: string; reservedUntil?: Date | null };
110	  }): Promise<{ count: number }>;
111	  update(args: {
112	    where: { id: string };
113	    data: { orderRef?: string | null; chargedCents?: number };
114	  }): Promise<{ id: string }>;
115	  deleteMany(args: { where: PromoWhere }): Promise<{ count: number }>;
116	  count(args?: { where?: PromoWhere }): Promise<number>;
117	};
118	
119	/** Anything that carries a `promoRedemption` delegate — the client or a tx client. */
120	type PromoClient = Prisma.TransactionClient | typeof db;
121	
122	/** The one place the stale-client cast lives. */
123	function promoDelegate(client: PromoClient): PromoDelegate {
124	  return (client as unknown as { promoRedemption: PromoDelegate }).promoRedemption;
125	}
