395	/** One-month credit for a flat-priced term (used by the game flow). */
396	export function firstMonthCreditCents(termPriceCents: number, termMonths: number): number {
397	  if (termMonths <= 1) return termPriceCents; // whole (single-month) term is free
398	  const oneMonth = Math.round(termPriceCents / termMonths);
399	  return Math.min(termPriceCents, oneMonth);
400	}
