1	/**
2	 * Checkout-coupon redemption — the RESERVATION lifecycle for the card/Stripe path.
3	 *
4	 * This mirrors lib/promo-redemption.ts's hold lifecycle (reserve → confirm → release
5	 * + a worker sweep + self-heal), applied to `CouponRedemption`. The wallet-atomic
6	 * grant still lives in lib/order.ts `claimOrderCoupon` and is unchanged; this module
7	 * is the machinery the CARD path needs so it never settles a discounted price up
8	 * front without an EXCLUSIVE hold behind it.
9	 *
10	 * WHY A COUPON IS HARDER THAN THE PROMO. The first-month-free promo is capped ONLY by
11	 * two unique constraints (1/account + 1/IP), so its reserve is a single guarded
12	 * INSERT. A coupon carries those two uniques AND a CONFIGURABLE global cap
13	 * (`Coupon.timesRedeemed` vs `maxRedemptions`). So a hold must ALSO occupy a slot in
14	 * that counter: reserve does the atomic conditional increment (the same one
15	 * `claimOrderCoupon` does), and release/self-heal/sweep DECREMENT it in lockstep when
16	 * a dead hold is deleted — otherwise an abandoned checkout would permanently burn a
17	 * global slot. A CONSUMED grant is never deleted here, so its increment stands.
18	 *
19	 * WHY A TYPED VIEW instead of `db.couponRedemption` directly: identical to
20	 * lib/promo-redemption.ts — the Prisma client in this tree is symlinked from prod and
21	 * regenerated only at deploy, so its types do not yet know the new reservation columns
22	 * (`state`, `reservedUntil`, `reservationToken`). Every raw-delegate access is
23	 * contained HERE behind `redemptionDelegate(...)`; when the client is regenerated the
24	 * runtime is identical and only these casts become redundant. (The `coupon` delegate is
25	 * already in the generated client, so `timesRedeemed` moves through the normal typed
26	 * client with no cast.)
27	 */
28	
29	import { randomUUID } from "crypto";
30	import { Prisma } from "@prisma/client";
31	import { db } from "./db";
32	
33	/**
34	 * Redemption row lifecycle. A wallet-atomic order inserts a CONSUMED grant in one step
35	 * (default state); the card/Stripe order first inserts a RESERVED hold (before the card
36	 * is charged) and later confirms it to CONSUMED. Both states physically occupy the two
37	 * unique slots AND a `timesRedeemed` slot, so a live hold blocks a second claim and
38	 * counts against the global cap exactly like a grant.
39	 */
40	export const COUPON_STATE = { RESERVED: "RESERVED", CONSUMED: "CONSUMED" } as const;
41	export type CouponState = (typeof COUPON_STATE)[keyof typeof COUPON_STATE];
42	
43	/** A minimal, honestly-typed shape of the row we read back. */
44	export type CouponRedemptionRow = {
45	  id: string;
46	  couponId: string;
47	  userId: string;
48	  ipHash: string | null;
49	  amountCents: number;
50	  context: string;
51	  state: string;
52	  reservedUntil: Date | null;
53	  reservationToken: string | null;
54	  createdAt: Date;
55	};
56	
57	type CouponRedemptionWhere = {
58	  couponId?: string;
59	  userId?: string;
60	  ipHash?: string;
61	  state?: string;
62	  reservationToken?: string;
63	  reservedUntil?: { lt: Date };
64	};
65	
66	/** The subset of the CouponRedemption delegate this module uses, hand-typed. */
67	type CouponRedemptionDelegate = {
68	  create(args: {
69	    data: {
70	      couponId: string;
71	      userId: string;
72	      ipHash: string | null;
73	      amountCents: number;
74	      context?: string;
75	      state?: string;
76	      reservedUntil?: Date | null;
77	      reservationToken?: string | null;
78	    };
79	    select?: { id: true };
80	  }): Promise<{ id: string }>;
81	  findFirst(args: {
82	    where: CouponRedemptionWhere;
83	    select?: { id: true; couponId?: true };
84	  }): Promise<{ id: string; couponId: string } | null>;
85	  findMany(args?: {
86	    where?: CouponRedemptionWhere;
87	    take?: number;
88	  }): Promise<CouponRedemptionRow[]>;
89	  updateMany(args: {
90	    where: CouponRedemptionWhere;
91	    data: { state?: string; reservedUntil?: Date | null };
92	  }): Promise<{ count: number }>;
93	  deleteMany(args: { where: CouponRedemptionWhere }): Promise<{ count: number }>;
94	};
95	
96	/** Anything that carries a `couponRedemption` (and `coupon`) delegate. */
97	type CouponClient = Prisma.TransactionClient | typeof db;
98	
99	/** The one place the stale-client cast lives (new reservation columns only). */
100	function redemptionDelegate(client: CouponClient): CouponRedemptionDelegate {
101	  return (client as unknown as { couponRedemption: CouponRedemptionDelegate }).couponRedemption;
102	}
103	
104	/**
105	 * Delete THIS claimant's own DEAD holds on a coupon — RESERVED rows whose `reservedUntil`
106	 * has passed and which were never confirmed (an abandoned/expired card checkout) — and
107	 * hand back the global slots they held (`timesRedeemed` decrement, one per deleted row).
108	 *
109	 * Strictly guarded — `state: RESERVED` AND `reservedUntil < now` — so a CONSUMED grant or
110	 * a still-live hold is NEVER touched, and the decrement can only ever undo an increment a
111	 * reserve made. This is the guarantee that an abandoned checkout can NEVER permanently
112	 * burn a customer's eligibility (per-person) or a coupon's last global slot: the very
113	 * next reserve/claim sweeps its own stale hold before contending. Runs inside the caller's
114	 * tx so the delete + decrement commit atomically. IP holds are cleared for the shared IP
115	 * slot too (a dead hold should block nobody).
116	 */
117	export async function releaseExpiredCouponHoldsFor(
118	  client: CouponClient,
119	  couponId: string,
120	  userId: string,
121	  ipHash: string | null,
122	): Promise<void> {
123	  const now = new Date();
124	  const d = redemptionDelegate(client);
125	  const delUser = await d.deleteMany({
126	    where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, userId },
127	  });
128	  if (delUser.count > 0) {
129	    await client.coupon.update({ where: { id: couponId }, data: { timesRedeemed: { decrement: delUser.count } } });
130	  }
131	  if (ipHash) {
132	    const delIp = await d.deleteMany({
133	      where: { couponId, state: COUPON_STATE.RESERVED, reservedUntil: { lt: now }, ipHash },
134	    });
135	    if (delIp.count > 0) {
136	      await client.coupon.update({ where: { id: couponId }, data: { timesRedeemed: { decrement: delIp.count } } });
137	    }
138	  }
139	}
