141	export type CouponReserveResult = { reserved: true; token: string } | { reserved: false; error: string };
142	
143	/**
144	 * THE CARD/STRIPE HOLD. Insert a RESERVED redemption BEFORE the card is charged, so a
145	 * second concurrent checkout can't also pass the per-person AND global caps and walk away
146	 * with a second discount. Runs in ONE transaction that:
147	 *   1. self-heals this claimant's own dead holds (so an earlier abandonment never blocks);
148	 *   2. enforces first-time-only (no prior paid server);
149	 *   3. does the atomic conditional `timesRedeemed` increment — the ONE thing between the
150	 *      last global slot and an over-redemption when N checkouts race for it;
151	 *   4. inserts the RESERVED row (P2002 on the two uniques => this account/IP already holds
152	 *      or redeemed) — which rolls the whole tx (increment included) back.
153	 * So exactly one of N racing checkouts holds the slot; losers get `{ reserved: false }` and
154	 * the caller re-quotes at FULL price (displayed === charged). The returned `token` is
155	 * stamped into the Checkout session metadata and is what confirm/release target.
156	 */
157	export async function reserveOrderCoupon(opts: {
158	  couponId: string;
159	  maxRedemptions: number | null;
160	  firstTimeOnly: boolean;
161	  userId: string;
162	  ipHash: string | null;
163	  amountCents: number;
164	  /** When this hold may be reaped if never confirmed (session lifetime + grace). */
165	  reservedUntil: Date;
166	}): Promise<CouponReserveResult> {
167	  const token = `cpr_${randomUUID()}`;
168	  try {
169	    return await db.$transaction(async (tx) => {
170	      // Clear this claimant's own dead holds first, so an earlier abandoned checkout
171	      // never blocks a new one and never holds a global slot hostage.
172	      await releaseExpiredCouponHoldsFor(tx, opts.couponId, opts.userId, opts.ipHash);
173	      if (opts.firstTimeOnly) {
174	        const prior = await tx.server.count({ where: { userId: opts.userId, isFree: false } });
175	        if (prior > 0) return { reserved: false as const, error: "This code is for first-time customers only." };
176	      }
177	      // Atomic conditional increment — the global cap gate. Same guard as claimOrderCoupon.
178	      const claim = await tx.coupon.updateMany({
179	        where:
180	          opts.maxRedemptions === null
181	            ? { id: opts.couponId, active: true }
182	            : { id: opts.couponId, active: true, timesRedeemed: { lt: opts.maxRedemptions } },
183	        data: { timesRedeemed: { increment: 1 } },
184	      });
185	      if (claim.count !== 1) return { reserved: false as const, error: "That code has reached its redemption limit." };
186	      // Insert the hold. A P2002 here (already held/redeemed by this account or IP) THROWS
187	      // out of the tx, rolling the increment above back with it — no leaked global slot.
188	      await redemptionDelegate(tx).create({
189	        data: {
190	          couponId: opts.couponId,
191	          userId: opts.userId,
192	          ipHash: opts.ipHash,
193	          amountCents: opts.amountCents,
194	          context: "order",
195	          state: COUPON_STATE.RESERVED,
196	          reservedUntil: opts.reservedUntil,
197	          reservationToken: token,
198	        },
199	        select: { id: true },
200	      });
201	      return { reserved: true as const, token };
202	    });
203	  } catch (e) {
204	    if (e instanceof Prisma.PrismaClientKnownRequestError && e.code === "P2002") {
205	      // Unique violation on (coupon,user) or (coupon,ipHash): already held or redeemed.
206	      return { reserved: false, error: "You’ve already used this code." };
207	    }
208	    throw e;
209	  }
210	}
