212	/**
213	 * Confirm a hold at fulfilment: flip its RESERVED row to CONSUMED, INSIDE the order's
214	 * charge tx so the grant commits with the money. The `state: RESERVED` guard makes it
215	 * idempotent (a replayed fulfil, or a race with the sweep, matches zero rows) and
216	 * guarantees we never "confirm" a hold that was already released. `timesRedeemed` is
217	 * NOT touched — it was already incremented at reserve — so there is never a second
218	 * discount or a double count. Returns true when THIS call did the confirming.
219	 */
220	export async function confirmOrderCouponReservation(
221	  tx: Prisma.TransactionClient,
222	  token: string,
223	): Promise<boolean> {
224	  const res = await redemptionDelegate(tx).updateMany({
225	    where: { reservationToken: token, state: COUPON_STATE.RESERVED },
226	    data: { state: COUPON_STATE.CONSUMED, reservedUntil: null },
227	  });
228	  return res.count === 1;
229	}
230	
231	/**
232	 * Release a hold (delete the RESERVED row AND hand its global slot back) so an
233	 * abandoned/expired checkout returns the customer's eligibility and the coupon's slot.
234	 * Guarded to `state: RESERVED` so it can NEVER delete a CONSUMED grant — a paid,
235	 * confirmed discount is never revoked by a late expiry event — and the `timesRedeemed`
236	 * decrement fires only when a RESERVED row was actually deleted (count === 1), so a race
237	 * with a concurrent confirm (which flips it to CONSUMED first) leaves the counter alone.
238	 * Called from the `checkout.session.expired` webhook and the worker sweep.
239	 */
240	export async function releaseOrderCouponReservation(token: string): Promise<void> {
241	  if (!token) return;
242	  await db.$transaction(async (tx) => {
243	    const d = redemptionDelegate(tx);
244	    const row = await d.findFirst({
245	      where: { reservationToken: token, state: COUPON_STATE.RESERVED },
246	      select: { id: true, couponId: true },
247	    });
248	    if (!row) return; // already consumed or already released — nothing to hand back.
249	    const del = await d.deleteMany({ where: { reservationToken: token, state: COUPON_STATE.RESERVED } });
250	    if (del.count === 1) {
251	      await tx.coupon.update({ where: { id: row.couponId }, data: { timesRedeemed: { decrement: 1 } } });
252	    }
253	  });
254	}
255	
256	/**
257	 * Backstop sweep: release every RESERVED hold whose `reservedUntil` has passed. Runs on
258	 * the worker so a dead hold (and its global slot) is reclaimed even if the
259	 * `checkout.session.expired` webhook is not configured or was missed. Each row is handed
260	 * to `releaseOrderCouponReservation` so the delete + `timesRedeemed` decrement stay
261	 * atomic and guarded per coupon. Returns how many were reaped. Bounded per pass.
262	 */
263	export async function sweepExpiredCouponReservations(now = new Date(), limit = 500): Promise<number> {
264	  const dead = await redemptionDelegate(db).findMany({
265	    where: { state: COUPON_STATE.RESERVED, reservedUntil: { lt: now } },
266	    take: limit,
267	  });
268	  let released = 0;
269	  for (const r of dead) {
270	    if (r.reservationToken) {
271	      await releaseOrderCouponReservation(r.reservationToken);
272	      released += 1;
273	    }
274	  }
275	  return released;
276	}
