466	  // Managed first-month-free eligibility. If this account/IP has ALREADY redeemed
467	  // the promo (or it's switched off), re-quote at FULL price so the wallet split,
468	  // the card leg and the stamped total are all full — the free month is a
469	  // once-per-person offer. The wallet path is self-correcting regardless (its
470	  // atomic claim inside placeOrder charges full on a lost claim), but the CARD
471	  // leg settles up front, so it MUST be priced full here or a repeat customer
472	  // gets a second discounted checkout. This mirrors the coupon guard below.
473	  // `|| null` matters: hashIp returns "" when the IP is unavailable, and an empty
474	  // string is a REAL value to the (promoId, ipHash) unique — it would collide
475	  // across every IP-less redemption and wrongly block them. NULLs are distinct.
476	  const promoIpHash = hashIp(clientIp(await headers()), process.env.AUTH_SECRET ?? "nxeon") || null;
477	  if (quote.promoCreditCents > 0 && !(await firstMonthFreeEligible(user.id, promoIpHash))) {
478	    quote = await orderQuote(intent, { suppressPromo: true });
479	  }
480	  const promoCampaign = promoCampaignFromCookie(await cookies());
481	
482	  const isAdmin = user.role === "ADMIN";
483	  const freePath = !!intent.free && isAdmin;
484	
485	  // Wallet-aware split. The customer's Review screen computes the exact same split
486	  // (lib/wallet-split.ts) from the same inputs, so what they see === what we charge.
487	  // `useWallet` defaults ON (only "0" turns it off) so existing forms keep applying
488	  // the balance. Free admin grants skip the split entirely (no money moves).
489	  const useWallet = formData.get("useWallet") !== "0";
