99	/**
100	 * Admin: generate OPEN invoices for every paid, active server that has no
101	 * invoice yet. Best-effort backfill — safe to run repeatedly.
102	 */
103	export async function regenerateMissingInvoices() {
104	  const admin = await requireAdmin();
105	  const servers = await db.server.findMany({
106	    where: { isFree: false, status: { not: "DELETING" } },
107	    include: { plan: true },
