1	/**
2	 * Coupons applied at CHECKOUT of a service (not fungible wallet credit).
3	 *
4	 * This is what makes "one free month on the Starter VPS" mean exactly that:
5	 *  - `serviceKind` + `planSlug` lock the coupon to a product family and/or a
6	 *    single plan, so it cannot be spent on a bigger plan or a different service;
7	 *  - `maxTermMonths` caps how many months of the term it may discount, so a
8	 *    percentage/free coupon cannot be stretched over a 12-month order to hand
9	 *    someone a year for free.
10	 *
11	 * Pure and framework-free so the money maths is unit-tested. The atomic
12	 * redemption claim (count + per-user + per-IP guards) lives in lib/order.ts.
13	 */
14	
15	export type CouponServiceKind = "ANY" | "VPS" | "GAME";
16	export type CouponKind = "PERCENT" | "FIXED_CENTS" | "CREDIT_CENTS";
17	
18	/** The coupon fields the order maths needs. */
19	export type OrderCoupon = {
20	  kind: CouponKind;
21	  value: number;
22	  serviceKind: CouponServiceKind;
23	  planSlug: string | null;
24	  maxTermMonths: number | null;
25	  active: boolean;
26	  expiresAt: Date | null;
27	  maxRedemptions: number | null;
28	  timesRedeemed: number;
29	  minAmountCents: number | null;
30	};
31	
32	export type OrderContext = {
33	  /** "VPS" or "GAME" — what the customer is buying. */
34	  serviceKind: "VPS" | "GAME";
35	  /** The plan's slug, matched against `coupon.planSlug`. */
36	  planSlug: string;
37	  /** The plan's REGULAR monthly price (before term/seasonal discounts), cents. */
38	  planMonthlyCents: number;
39	  /** The term the customer chose, in months. */
40	  termMonths: number;
41	  /** What the plan portion of the order actually costs (first-term, cents). */
42	  planChargeCents: number;
43	};
44	
45	/** Does this coupon apply to the thing being bought? */
46	export function couponMatchesService(coupon: Pick<OrderCoupon, "serviceKind" | "planSlug">, ctx: Pick<OrderContext, "serviceKind" | "planSlug">): boolean {
47	  if (coupon.serviceKind !== "ANY" && coupon.serviceKind !== ctx.serviceKind) return false;
48	  if (coupon.planSlug && coupon.planSlug.toLowerCase() !== ctx.planSlug.toLowerCase()) return false;
49	  return true;
50	}
51	
52	export type CouponOrderVerdict =
53	  | { ok: true; discountCents: number; label: string }
54	  | { ok: false; error: string };
55	
56	/** "1 month free on Starter", "20% off (first 1 month)", "$5.00 off"… */
57	function describe(coupon: Pick<OrderCoupon, "kind" | "value">, cappedMonths: number, termMonths: number): string {
58	  const monthNote = cappedMonths < termMonths ? ` (first ${cappedMonths} month${cappedMonths === 1 ? "" : "s"})` : "";
59	  switch (coupon.kind) {
60	    case "PERCENT":
61	      return coupon.value >= 100 ? `${cappedMonths} month${cappedMonths === 1 ? "" : "s"} free` : `${coupon.value}% off${monthNote}`;
62	    case "FIXED_CENTS":
63	      return `$${(coupon.value / 100).toFixed(2)} off`;
64	    default:
65	      return "discount";
66	  }
67	}
68	
69	/**
70	 * Validate a coupon against an order and compute the discount, in cents.
71	 *
72	 * Only PERCENT and FIXED_CENTS apply at checkout (CREDIT_CENTS is a wallet-credit
73	 * kind and is rejected here). The discount is bounded three ways and never
74	 * exceeds the plan charge:
75	 *   - PERCENT is applied to at most `maxTermMonths` months of the plan's monthly
76	 *     price — THE cap that stops "100% off" on a 12-month order being a year free;
77	 *   - FIXED_CENTS is a flat amount, still capped at the plan charge;
78	 *   - both are clamped to `planChargeCents` so a coupon can zero a line but never
79	 *     make it negative (which would mint wallet credit).
80	 */
81	export function couponOrderDiscountCents(coupon: OrderCoupon, ctx: OrderContext, now: Date): CouponOrderVerdict {
82	  if (!coupon.active) return { ok: false, error: "That code isn’t valid." };
83	  if (coupon.kind === "CREDIT_CENTS") return { ok: false, error: "That code is for wallet credit, not checkout." };
84	  if (coupon.expiresAt && coupon.expiresAt.getTime() < now.getTime()) return { ok: false, error: "That code has expired." };
85	  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
86	    return { ok: false, error: "That code has been fully claimed." };
87	  }
88	  if (!couponMatchesService(coupon, ctx)) {
89	    return { ok: false, error: "That code doesn’t apply to this plan." };
90	  }
91	  if (coupon.minAmountCents !== null && ctx.planChargeCents < coupon.minAmountCents) {
92	    return { ok: false, error: `This code needs an order of at least $${(coupon.minAmountCents / 100).toFixed(2)}.` };
93	  }
94	
95	  const term = Math.max(1, Math.floor(ctx.termMonths || 1));
96	  // How many months the discount may touch — the "no year free" cap.
97	  let cappedMonths = coupon.maxTermMonths && coupon.maxTermMonths > 0 ? Math.min(coupon.maxTermMonths, term) : term;
98	  // Defence in depth for a 100%-off PERCENT code with NO month cap: without this it would
99	  // zero the ENTIRE term, gifting a whole 12/24/36-month VPS for free. Coupon creation now
100	  // refuses such a code (lib/actions-growth.ts adminCreateCoupon), but any row that predates
101	  // that guard is clamped HERE to a single month — the safe floor a "100% off" should mean.
102	  if (coupon.kind === "PERCENT" && coupon.value >= 100 && !(coupon.maxTermMonths && coupon.maxTermMonths > 0)) {
103	    cappedMonths = 1;
104	  }
105	
106	  let discount: number;
107	  if (coupon.kind === "PERCENT") {
108	    const pct = Math.min(100, Math.max(0, coupon.value));
109	    // The discountable base is the capped months at the REGULAR monthly price —
110	    // not the whole (possibly term-discounted) charge — so "1 month free" is one
111	    // month of the plan regardless of a 12-month term's own discount.
112	    const base = Math.min(ctx.planMonthlyCents * cappedMonths, ctx.planChargeCents);
113	    discount = Math.round((base * pct) / 100);
114	  } else {
115	    discount = coupon.value;
116	  }
117	
118	  discount = Math.max(0, Math.min(discount, ctx.planChargeCents));
119	  if (discount <= 0) return { ok: false, error: "That code has no effect on this order." };
120	  return { ok: true, discountCents: discount, label: describe(coupon, cappedMonths, term) };
121	}
122	
123	/**
124	 * A stable, non-reversible hash of a claimant IP, for the once-per-person guard.
125	 * We store the hash, never the raw IP — the check only needs equality, and a
126	 * plaintext IP log of everyone who claimed a promo is a liability we don't want.
127	 * `salt` comes from the app secret so hashes aren't portable across deployments.
128	 */
129	export function hashIp(ip: string, salt: string): string {
130	  const clean = String(ip ?? "").trim();
131	  if (!clean) return "";
132	  // Lazy require so this module stays importable in any context; crypto is builtin.
133	  const { createHash } = require("node:crypto") as typeof import("node:crypto");
134	  return createHash("sha256").update(`${salt}:${clean}`).digest("hex");
135	}
136	
137	/** Human summary of a coupon's scope for the admin list / customer preview. */
138	export function describeCouponScope(coupon: Pick<OrderCoupon, "serviceKind" | "planSlug" | "maxTermMonths">): string {
139	  const parts: string[] = [];
140	  if (coupon.planSlug) parts.push(`${coupon.planSlug} plan only`);
141	  else if (coupon.serviceKind !== "ANY") parts.push(`${coupon.serviceKind} only`);
142	  if (coupon.maxTermMonths) parts.push(`max ${coupon.maxTermMonths} month${coupon.maxTermMonths === 1 ? "" : "s"}`);
143	  return parts.join(" · ") || "any service";
144	}
