343	// ---------- 4. Self-serve cancel / terminate (+ prorated refund) ----------
344	
345	/**
346	 * Customer-initiated cancellation of a VPS / game server. Two modes:
347	 *
348	 *   • "period_end"  — stop auto-renew and keep the server running until `expiresAt`.
349	 *                     No money moves; the paid term is honoured to its end. Default
350	 *                     and always-safe choice.
351	 *   • "immediate"   — terminate NOW: enqueue the SAME audited DELETE job the manual
352	 *                     delete uses (worker destroys the VM), and — for a standard VPS
353	 *                     with unused paid time — credit the prorated refund to the WALLET
354	 *                     (never a Stripe refund; safer and reversible) in the same
355	 *                     transaction, with a ledger line and a credit-note invoice.
356	 *
357	 * Ownership-guarded and `assertNotImpersonating` (this both destroys a resource and
358	 * can move money — an admin must not do either on a customer's behalf). Respects the
359	 * one-in-flight-job invariant. The confirm dialog in the UI carries the data-retention
360	 * warning and the refund figure.
361	 */
362	export async function cancelService(
363	  serverId: string,
364	  mode: "immediate" | "period_end",
365	): Promise<{ error?: string; ok?: boolean; refundCents?: number; message?: string }> {
366	  // Moves money and destroys a resource — never while impersonating.
367	  await assertNotImpersonating();
368	  const { user, server } = await ownedServer(serverId);
369	
370	  if (server.status === "DELETING") return { error: "This server is already being cancelled." };
371	
372	  // ---- Cancel at period end: just stop auto-renew, keep the server to expiry. ----
373	  if (mode === "period_end") {
374	    if (server.isFree || !server.expiresAt) {
375	      return { error: "This server has no billing term to cancel — use immediate termination to remove it." };
376	    }
377	    if (!server.autoRenew) {
378	      return { ok: true, message: `Auto-renew is already off. This server stays active until ${server.expiresAt.toISOString().slice(0, 10)}, then stops.` };
379	    }
380	    await db.server.update({ where: { id: server.id }, data: { autoRenew: false } });
381	    await db.auditLog.create({
382	      data: { userId: user.id, action: "server.cancel_period_end", detail: serverId },
383	    });
384	    revalidatePath(`/dashboard/servers/${serverId}`);
385	    return {
386	      ok: true,
387	      message: `Auto-renew turned off. This server keeps running until ${server.expiresAt.toISOString().slice(0, 10)}, then stops automatically. You can turn auto-renew back on any time before then.`,
388	    };
389	  }
390	
391	  // ---- Immediate termination (+ prorated wallet refund). ----
392	  if (await hasInflightJob(serverId)) {
393	    return { error: "Another operation is already in progress on this server. Wait for it to finish, then try again." };
394	  }
395	
396	  const refundCents = terminationRefundCents({
397	    isFree: server.isFree,
398	    expiresAt: server.expiresAt,
399	    isGame: !!server.gamePlanId,
400	    planMonthlyCents: server.plan.priceCents,
401	    termMonths: server.termMonths,
402	    termPromoPercent: server.termPromoPercent,
403	    // Authoritative refund basis: the real plan cash collected for the term, net of
404	    // promo AND coupon. Null on legacy rows → the helper falls back to the (safe,
405	    // never-over-refunding) termPromoPercent formula.
406	    refundableTermCents: server.refundableTermCents,
407	    annualDiscountPct: frozenAnnualDiscountPct(server) ?? (await annualDiscountPct()),
408	  });
409	
410	  // One INTERACTIVE transaction whose FIRST act is a compare-and-swap on status: flip
411	  // to DELETING only if it is not already DELETING. A double-click / retry that loses
412	  // the race (`adv.count === 0`) does NOTHING — no second refund, no second DELETE job.
413	  // Only the winner issues the refund credit + ledger line + credit-note + DELETE job,
414	  // so refund and termination commit together and can never both run twice. (The old
415	  // array form flipped status unconditionally, so N concurrent calls all refunded.)
416	  const won = await db.$transaction(async (tx) => {
417	    const adv = await tx.server.updateMany({
418	      where: { id: server.id, status: { not: "DELETING" } },
419	      data: { status: "DELETING", autoRenew: false },
420	    });
421	    if (adv.count !== 1) return false; // lost the race — another call already claimed it
422	
423	    if (refundCents > 0) {
424	      await tx.user.update({
425	        where: { id: server.userId },
426	        data: { balanceCents: { increment: refundCents } },
427	      });
428	      await tx.walletTransaction.create({
429	        data: {
430	          userId: server.userId,
431	          amountCents: refundCents,
432	          description: `Cancellation refund (unused term) — ${server.hostname}`,
433	        },
434	      });
435	      // A credit-note invoice for the refund, so the ledger line has a matching
436	      // billing document the customer can download. Marked REFUNDED.
437	      await tx.invoice.create({
438	        data: invoiceCreateData({
439	          userId: server.userId,
440	          description: `Cancellation refund — ${server.hostname}`,
441	          status: "REFUNDED",
442	          lineItems: [
443	            {
444	              description: `Prorated refund for unused term — ${server.hostname}`,
445	              qty: 1,
446	              unitCents: refundCents,
447	              amountCents: refundCents,
448	            },
449	          ],
450	        }),
451	      });
452	    }
453	    await tx.job.create({ data: { type: "DELETE", serverId } });
454	    await tx.auditLog.create({
455	      data: {
456	        userId: user.id,
457	        action: "server.cancel_immediate",
458	        detail: `${serverId} refund=${refundCents}`,
459	      },
460	    });
461	    return true;
462	  });
463	
464	  if (!won) {
465	    return { error: "This server is already being cancelled." };
466	  }
467	
468	  if (refundCents > 0) {
469	    await db.notification
470	      .create({
471	        data: {
472	          userId: server.userId,
473	          title: `Refund of $${(refundCents / 100).toFixed(2)} credited to your wallet`,
474	          body: `We refunded the unused portion of ${server.hostname}'s term as wallet credit. Your data on this server is being erased and cannot be recovered.`,
475	          href: "/dashboard/billing",
476	        },
477	      })
478	      .catch(() => {});
479	  }
480	
481	  revalidatePath(`/dashboard/servers/${serverId}`);
482	  return {
483	    ok: true,
484	    refundCents,
485	    message:
486	      refundCents > 0
487	        ? `Server termination started. $${(refundCents / 100).toFixed(2)} for the unused part of your term has been credited to your wallet. All data on this server is being permanently erased.`
488	        : `Server termination started. All data on this server is being permanently erased.`,
489	  };
490	}
