  // paid to BOTH the referrer and the referred user, so a stray digit costs twice
  // per signup and scales with signup volume. 100_000 cents = $1,000 a side is
  // already absurd; anything beyond it is certainly a typo.
  const reward = Math.min(
    Math.max(await getSettingInt("referral_reward_cents", referralRewardCents()), 0),
    100_000
  );
